/** 路径 -> 源码。写进 Pyodide 的虚拟文件系统时按这个 key 落盘 */
export const NANOTORCH_SOURCES: Record<string, string> = {
  "nanotorch/__init__.py": "\"\"\"nanotorch —— PyTorch 的一个严格子集，跑在 WebAssembly 上。\n\n学员在这里写的代码，贴进 PyTorch 就能跑：模块的组织方式、算子的名字、\n优化器的参数、训练循环的形状，全是一样的。\n\n    import nanotorch as nt\n    from nanotorch import nn, functional as F\n\n    class Block(nn.Module):\n        def __init__(self, cfg):\n            super().__init__()\n            self.norm1 = nn.RMSNorm(cfg.dim)\n            self.attn = nn.CausalSelfAttention(cfg.dim, cfg.n_head, cfg.n_kv_head, seed=1)\n        def forward(self, x, cos, sin, b, s):\n            return x + self.attn(self.norm1(x), cos, sin, b, s)\n\n## 和 PyTorch 的差别（就这几条，其余都一样）\n\n| | nanotorch | PyTorch |\n| --- | --- | --- |\n| 广播 | **没有**，形状必须严格对上 | 有 |\n| dtype | f32 / f64 | 十几种 |\n| 设备 | 只有一个（wasm 线性内存） | cpu / cuda / … |\n| 算子粒度 | 粗（rmsnorm / attention 各一整块） | 粗细都有 |\n| 权重排布 | `Linear` 存 [in, out] | 存 [out, in] |\n\n**为什么慢的地方它就是慢**：纯 Python 的循环比 JS 慢约 300 倍（实测 16 MFLOP/s）。\n所以代码必须向量化 —— 而现实里也是这条规矩，没有人在 PyTorch 里逐元素写 for 循环。\n\n## 实现分几层\n\n    nanotorch/          ← 你现在读的这一层，Python，看得见改得动\n      tensor.py         Tensor 与反向传播的带\n      functional.py     算子 + 它们各自的反向\n      nn.py             Module / Linear / RMSNorm / Embedding / 注意力 / MLP\n      optim.py          AdamW 与学习率调度\n      _bridge.py        往下的那道缝（只传整数 id，不搬数）\n         ↓\n    JS 桥               张量、显存、**全部计量**\n         ↓\n    WASM 算子核         37KB，f32 带 SIMD（实测 37–42 GFLOP/s）\n\n这个分层和 PyTorch 自己的结构是同一个形状（Python 前端 + C++ kernel），\n不是为了偷懒发明的。\n\"\"\"\n\nfrom .tensor import Tensor, zeros, parameter\nfrom . import functional\nfrom . import functional as F\nfrom . import nn\nfrom . import optim\nfrom ._bridge import phase, add_tokens, mark, release\n\n__all__ = [\n    \"Tensor\", \"zeros\", \"parameter\",\n    \"functional\", \"F\", \"nn\", \"optim\",\n    \"phase\", \"add_tokens\", \"mark\", \"release\",\n]\n\n__version__ = \"0.1.0\"\n",
  "nanotorch/_bridge.py": "\"\"\"和算子核之间的那一层。\n\n学员不需要读这个文件，但**读了也不亏** —— 它就是 PyTorch 里\n`torch._C` 那一层在我们这儿的对应物：Python 只管形状与调度，\n真正的浮点数始终躺在 wasm 的线性内存里，这边拿到的只是一个整数 id。\n\n跨语言搬一个 [256, 64] 的张量要几万次转换；搬一个整数是 1.05 µs。\n一步训练约 150 次调用，合计 0.22 ms —— 相对一步 5.6 ms 是噪声。\n这条路能成立全靠这个划法。\n\"\"\"\n\n# JS 侧用 registerJsModule 注册进来的桥。\n# 不走 `import js` + globalThis：那样同一个进程里的多个运行时会互相覆盖。\nimport llmlab_bridge as _B\n\n\ndef alloc(count, dtype=\"f32\", role=\"activation\", name=\"\"):\n    return _B.alloc(count, dtype, role, name)\n\n\ndef mark():\n    return _B.mark()\n\n\ndef release(m):\n    _B.release(m)\n\n\ndef phase(name):\n    \"\"\"标一下现在处在前向 / 反向 / 优化器的哪一段。\n\n    门槛要分开读三段的 FLOPs（比如「反向不许超过前向的 2.2 倍」），\n    所以这个标记不是可有可无的装饰。\n    \"\"\"\n    _B.phase(name)\n\n\ndef add_tokens(n):\n    _B.add_tokens(n)\n\n\ndef set_i32(handle, values):\n    _B.set_i32(handle, values)\n\n\ndef set_f(handle, values):\n    _B.set_f(handle, values)\n\n\ndef get_f(handle, count):\n    return list(_B.get_f(handle, count))\n\n\ndef item(handle, index=0):\n    return _B.item(handle, index)\n\n\ndef fill(handle, value):\n    _B.fill(handle, value)\n\n\ndef fill_normal(handle, seed, std):\n    _B.fill_normal(handle, seed, std)\n\n\ndef fill_rope(cos_h, sin_h, block_size, head_dim, base):\n    _B.fill_rope(cos_h, sin_h, block_size, head_dim, base)\n\n\n# ---- 算子。参数与 JS 那边一一对应，不做任何加工 ----\n\ngemm_nn = _B.gemm_nn\ngemm_tn_acc = _B.gemm_tn_acc\ngemm_nt = _B.gemm_nt\nadd_inplace = _B.add_inplace\nscale_inplace = _B.scale_inplace\ncopy = _B.copy\nsumsq = _B.sumsq\nrmsnorm_fwd = _B.rmsnorm_fwd\nrmsnorm_bwd = _B.rmsnorm_bwd\nswiglu_fwd = _B.swiglu_fwd\nswiglu_bwd = _B.swiglu_bwd\nrope_fwd = _B.rope_fwd\nrope_bwd = _B.rope_bwd\nattn_fwd = _B.attn_fwd\nattn_bwd = _B.attn_bwd\ncross_entropy = _B.cross_entropy\ncross_entropy_bwd = _B.cross_entropy_bwd\nembed_fwd = _B.embed_fwd\nembed_bwd = _B.embed_bwd\nadamw = _B.adamw\n",
  "nanotorch/functional.py": "\"\"\"算子的函数式接口，每个都自带反向。\n\n命名与参数尽量对着 `torch.nn.functional` —— 学员在这里写的\n`F.rms_norm(x, weight)`、`F.scaled_dot_product_attention(q, k, v, is_causal=True)`，\n换到 PyTorch 上是同一个名字同一个意思。\n\n每个函数的结构都一样：\n\n    1. 核形状\n    2. 分配输出\n    3. 调前向\n    4. 挂一个闭包，反向时把梯度散给上游\n\n第 9–11 关要学员自己把第 4 步写出来，所以这些闭包是**这个项目的教学正文**，\n不是实现细节。\n\"\"\"\n\nfrom . import _bridge as B\nfrom .tensor import Tensor, zeros\n\n\ndef _rows(shape):\n    \"\"\"把 [..., d] 摊平成 (行数, d)。所有逐行算子都按这个约定。\"\"\"\n    n = 1\n    for d in shape[:-1]:\n        n *= d\n    return n, shape[-1]\n\n\ndef add(a, b):\n    \"\"\"逐元素相加。残差连接就是它。\n\n    反向极其简单 —— 加法的梯度是**原样分给两边**。\n    简单到值得说一句：残差之所以能让深网络训得动，一半的原因就在这里，\n    梯度从输出到输入有一条不经过任何缩放的通路。\n    \"\"\"\n    assert a.shape == b.shape, f\"相加的两边形状要一致：{a.shape} vs {b.shape}\"\n    n = a.numel\n    out = Tensor(a.shape, a.dtype, name=\"add\")\n    B.copy(out.handle, a.handle, n)\n    B.add_inplace(out.handle, b.handle, n)\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        if a.requires_grad:\n            B.add_inplace(a.ensure_grad().handle, go.handle, n)\n        if b.requires_grad:\n            B.add_inplace(b.ensure_grad().handle, go.handle, n)\n\n    out.requires_grad = a.requires_grad or b.requires_grad\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (a, b)\n    return out\n\n\ndef linear(x, weight):\n    \"\"\"y = x @ weight。\n\n    `weight` 是 [in, out]，和 PyTorch 的 `nn.Linear`（存 [out, in]）**转置着来** ——\n    这是我们的算子核更自然的排布。`nn.Linear` 那一层会把这件事藏起来，\n    所以学员在模型代码里看到的仍然是熟悉的形状。\n    \"\"\"\n    rows, din = _rows(x.shape)\n    assert weight.dim() == 2 and weight.shape[0] == din, \\\n        f\"linear 的形状对不上：x 的最后一维是 {din}，weight 是 {weight.shape}\"\n    dout = weight.shape[1]\n    out = Tensor(x.shape[:-1] + (dout,), x.dtype, name=\"linear\")\n    B.gemm_nn(x.handle, weight.handle, out.handle, rows, dout, din)\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        if weight.requires_grad:\n            B.gemm_tn_acc(x.handle, go.handle, weight.ensure_grad().handle, rows, dout, din)\n        if x.requires_grad:\n            # dX = dY @ W^T，累加到 x 已有的梯度上（x 可能被多处用到）\n            tmp = Tensor(x.shape, x.dtype, name=\"dlinear\")\n            B.gemm_nt(go.handle, weight.handle, tmp.handle, rows, din, dout)\n            B.add_inplace(x.ensure_grad().handle, tmp.handle, x.numel)\n\n    out.requires_grad = x.requires_grad or weight.requires_grad\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (x, weight)\n    return out\n\n\ndef rms_norm(x, weight, eps=1e-5):\n    \"\"\"沿最后一维做 RMSNorm。对应 `torch.nn.functional.rms_norm`。\"\"\"\n    rows, d = _rows(x.shape)\n    assert weight.numel == d, f\"rms_norm 的增益长度应为 {d}，实际 {weight.numel}\"\n    out = Tensor(x.shape, x.dtype, name=\"rmsnorm\")\n    inv = Tensor((rows,), x.dtype, name=\"rmsnorm.inv\")\n    B.rmsnorm_fwd(x.handle, weight.handle, out.handle, inv.handle, rows, d, eps)\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        tmp = Tensor(x.shape, x.dtype, name=\"drmsnorm\")\n        B.rmsnorm_bwd(go.handle, x.handle, weight.handle, inv.handle,\n                      weight.ensure_grad().handle, tmp.handle, rows, d)\n        if x.requires_grad:\n            B.add_inplace(x.ensure_grad().handle, tmp.handle, x.numel)\n\n    out.requires_grad = x.requires_grad or weight.requires_grad\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (x, weight)\n    return out\n\n\ndef swiglu(gate, up):\n    \"\"\"silu(gate) * up。\n\n    对应 PyTorch 里手写的 `F.silu(gate) * up` —— 现代 LLM 的前馈层就这一句，\n    只是真实现里会把两个投影合成一个 gemm 再劈开。\n    \"\"\"\n    assert gate.shape == up.shape, f\"swiglu 两边形状要一致：{gate.shape} vs {up.shape}\"\n    n = gate.numel\n    out = Tensor(gate.shape, gate.dtype, name=\"swiglu\")\n    B.swiglu_fwd(gate.handle, up.handle, out.handle, n)\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        dgate = Tensor(gate.shape, gate.dtype, name=\"dgate\")\n        dup = Tensor(up.shape, up.dtype, name=\"dup\")\n        B.swiglu_bwd(go.handle, gate.handle, up.handle, dgate.handle, dup.handle, n)\n        if gate.requires_grad:\n            B.add_inplace(gate.ensure_grad().handle, dgate.handle, n)\n        if up.requires_grad:\n            B.add_inplace(up.ensure_grad().handle, dup.handle, n)\n\n    out.requires_grad = gate.requires_grad or up.requires_grad\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (gate, up)\n    return out\n\n\ndef rope_tables(seq, head_dim, base=10000.0):\n    \"\"\"预算 RoPE 的 cos / sin 表，返回 `(cos, sin)`。\n\n    表只跟位置和头维有关，跟数据无关，所以整个训练里算一次就够。\n    真 PyTorch 里这一步同样是预算好挂在模块上的（Llama 叫 `rotary_emb`）。\n\n    在 JS 侧填：Python 里逐元素写这张表要走两万次解释器循环，\n    而它比整个前向还慢 —— 这是「纯 Python 的循环慢 300 倍」的第一个受害者。\n    \"\"\"\n    assert head_dim % 2 == 0, f\"RoPE 要求头维是偶数，拿到 {head_dim}\"\n    half = head_dim // 2\n    # role=\"data\"：这张表整个训练里都在，不该被每步的 release 推平\n    cos = Tensor((seq, half), role=\"data\", name=\"rope.cos\")\n    sin = Tensor((seq, half), role=\"data\", name=\"rope.sin\")\n    B.fill_rope(cos.handle, sin.handle, seq, head_dim, base)\n    return cos, sin\n\n\ndef rope(x, cos, sin, batch, seq, heads, head_dim):\n    \"\"\"就地把每个头的前后半维当成复数旋转。\n\n    **这个算子是就地的**，所以它返回的是同一个 handle 包成的新 Tensor ——\n    上游那份在旋转之后就不再是原来的值了。真 PyTorch 的实现一般不就地，\n    这里就地是为了省一块 [B, S, H, hd]；边界写在这里，别在别处假设 x 还是旧的。\n    \"\"\"\n    B.rope_fwd(x.handle, cos.handle, sin.handle, batch, seq, heads, head_dim)\n    out = Tensor(x.shape, x.dtype, name=\"rope\", handle=x.handle)\n    out.requires_grad = x.requires_grad\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        # 旋转矩阵的转置就是转 −θ，所以反向也是就地的\n        B.rope_bwd(go.handle, cos.handle, sin.handle, batch, seq, heads, head_dim)\n        x.grad = go\n\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (x,)\n    return out\n\n\ndef scaled_dot_product_attention(q, k, v, batch, seq, heads, kv_heads, head_dim):\n    \"\"\"因果注意力，支持 GQA。对应 `F.scaled_dot_product_attention(..., is_causal=True)`。\n\n    `att` 那块是 [B, H, S, S] —— **它就是那块 O(S²) 的显存**。\n    B=16 / H=8 / S=128 时每层 8.4MB，比一个 75k 参数的模型本身还大。\n    FlashAttention 存在的理由，在这个尺度上就已经是一个能量出来的数了。\n    \"\"\"\n    # 输出跟 q 同形。**不要写死成 (batch, seq, heads*head_dim)** ——\n    # 上游可能是摊平的 (rows, dim)，写死之后残差那一步会因为 rank 不同而挂，\n    # 而元素数是一样的，所以错得很像「形状约定没定清楚」。事实上就是。\n    assert q.numel == batch * seq * heads * head_dim, \\\n        f\"q 有 {q.numel} 个元素，按 B={batch} S={seq} H={heads} hd={head_dim} 应该是 \" \\\n        f\"{batch * seq * heads * head_dim}\"\n    assert k.numel == batch * seq * kv_heads * head_dim, \"k 的元素数与 kv_heads 对不上\"\n    assert v.numel == k.numel, \"v 要和 k 同形\"\n    out = Tensor(q.shape, q.dtype, name=\"attn.out\")\n    att = Tensor((batch, heads, seq, seq), q.dtype, name=\"attn.probs\")\n    B.attn_fwd(q.handle, k.handle, v.handle, att.handle, out.handle,\n               batch, seq, heads, kv_heads, head_dim)\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        dq = zeros(q.shape, q.dtype, name=\"dq\")\n        dk = zeros(k.shape, k.dtype, name=\"dk\")\n        dv = zeros(v.shape, v.dtype, name=\"dv\")\n        dp = zeros((seq,), q.dtype, name=\"attn.scratch\")\n        B.attn_bwd(go.handle, q.handle, k.handle, v.handle, att.handle,\n                   dq.handle, dk.handle, dv.handle, dp.handle,\n                   batch, seq, heads, kv_heads, head_dim)\n        if q.requires_grad:\n            B.add_inplace(q.ensure_grad().handle, dq.handle, q.numel)\n        if k.requires_grad:\n            B.add_inplace(k.ensure_grad().handle, dk.handle, k.numel)\n        if v.requires_grad:\n            B.add_inplace(v.ensure_grad().handle, dv.handle, v.numel)\n\n    out.requires_grad = q.requires_grad or k.requires_grad or v.requires_grad\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (q, k, v)\n    return out\n\n\ndef embedding(table, idx, rows, dim):\n    \"\"\"按 token id 取行。对应 `F.embedding`。\"\"\"\n    out = Tensor((rows, dim), table.dtype, name=\"embedding\")\n    B.embed_fwd(table.handle, idx.handle, out.handle, rows, dim)\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        # 散射累加：同一个 token 在一个 batch 里出现多次，梯度要加起来\n        B.embed_bwd(go.handle, idx.handle, table.ensure_grad().handle, rows, dim)\n\n    out.requires_grad = table.requires_grad\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (table,)\n    return out\n\n\ndef linear_tied(x, table, rows, dim, vocab):\n    \"\"\"logits = x @ table^T —— lm_head 与词嵌入共享权重。\n\n    注意 `table` 的梯度在这里加一次、在 `embedding` 的反向里再加一次。\n    **两次都要**，这正是权重共享的意思；漏掉任何一次，前向照样对、loss 照样降，\n    只有梯度检验抓得到。\n    \"\"\"\n    out = Tensor((rows, vocab), x.dtype, name=\"logits\")\n    B.gemm_nt(x.handle, table.handle, out.handle, rows, vocab, dim)\n\n    def backward():\n        go = out.grad\n        if go is None:\n            return\n        if table.requires_grad:\n            B.gemm_tn_acc(go.handle, x.handle, table.ensure_grad().handle, rows, dim, vocab)\n        if x.requires_grad:\n            tmp = Tensor(x.shape, x.dtype, name=\"dlogits.x\")\n            B.gemm_nn(go.handle, table.handle, tmp.handle, rows, dim, vocab)\n            B.add_inplace(x.ensure_grad().handle, tmp.handle, x.numel)\n\n    out.requires_grad = x.requires_grad or table.requires_grad\n    if out.requires_grad:\n        out._backward = backward\n        out._parents = (x, table)\n    return out\n\n\ndef cross_entropy(logits, targets, rows, vocab, mask=None):\n    \"\"\"行 softmax + 交叉熵，返回**平均** loss（一个标量 Tensor）。\n\n    `mask` 给 SFT 用：标 0 的行不贡献梯度。注意**前向报的仍是全部位置的平均** ——\n    要屏蔽的话学员得自己在报数时也过一遍 mask。这个边界写在这里，\n    因为「以为屏蔽了、其实没有」是 SFT 那一关最容易踩的坑。\n    \"\"\"\n    probs = Tensor((rows, vocab), logits.dtype, name=\"probs\")\n    value = B.cross_entropy(logits.handle, targets.handle, probs.handle, rows, vocab)\n\n    loss = Tensor((1,), logits.dtype, name=\"loss\")\n    loss.set_([value])\n\n    def backward():\n        d = Tensor((rows, vocab), logits.dtype, name=\"dlogits\")\n        B.cross_entropy_bwd(probs.handle, targets.handle,\n                            mask.handle if mask is not None else -1,\n                            d.handle, rows, vocab, 1.0 / rows)\n        if logits.requires_grad:\n            B.add_inplace(logits.ensure_grad().handle, d.handle, logits.numel)\n\n    loss.requires_grad = logits.requires_grad\n    if loss.requires_grad:\n        loss._backward = backward\n        loss._parents = (logits,)\n    # Python 侧要拿这个数打印曲线，附在张量上省一次跨语言读\n    loss.value = value  # type: ignore[attr-defined]\n    return loss\n",
  "nanotorch/nn.py": "\"\"\"模块系统。形状与用法照着 `torch.nn` 来。\n\n学员写的模型长这样：\n\n    class Block(nn.Module):\n        def __init__(self, cfg):\n            super().__init__()\n            self.attn = Attention(cfg)\n            self.mlp = MLP(cfg)\n        def forward(self, x):\n            x = x + self.attn(self.norm1(x))\n            return x + self.mlp(self.norm2(x))\n\n—— 和 nanoGPT 里那段是同一个形状，这正是选 Python 的理由。\n\"\"\"\n\nfrom . import functional as F\nfrom .tensor import Tensor, parameter, zeros\n\n\nclass Module:\n    \"\"\"所有模块的基类。\n\n    比 `torch.nn.Module` 少很多东西（没有 buffer、没有 hook、没有 train/eval），\n    但**参数的收集方式是一样的**：递归遍历子模块。\n    \"\"\"\n\n    def __init__(self):\n        self._params = {}\n        self._modules = {}\n\n    def __setattr__(self, name, value):\n        if isinstance(value, Tensor) and value.requires_grad:\n            self.__dict__.setdefault(\"_params\", {})[name] = value\n        elif isinstance(value, Module):\n            self.__dict__.setdefault(\"_modules\", {})[name] = value\n        object.__setattr__(self, name, value)\n\n    def parameters(self):\n        \"\"\"按**确定的顺序**返回全部参数。\n\n        顺序确定这件事不是洁癖：优化器按这个顺序更新，\n        而「同一份代码跑两遍逐位一致」要求每一步的浮点运算顺序都一样。\n        Python 3.7+ 的 dict 保序，所以这里天然是稳的。\n        \"\"\"\n        out = []\n        for p in self.__dict__.get(\"_params\", {}).values():\n            out.append(p)\n        for m in self.__dict__.get(\"_modules\", {}).values():\n            out.extend(m.parameters())\n        return out\n\n    def named_parameters(self, prefix=\"\"):\n        out = []\n        for name, p in self.__dict__.get(\"_params\", {}).items():\n            out.append((f\"{prefix}{name}\", p))\n        for name, m in self.__dict__.get(\"_modules\", {}).items():\n            out.extend(m.named_parameters(f\"{prefix}{name}.\"))\n        return out\n\n    def zero_grad(self):\n        for p in self.parameters():\n            p.zero_grad()\n\n    def num_parameters(self):\n        return sum(p.numel for p in self.parameters())\n\n    def forward(self, *args, **kwargs):\n        raise NotImplementedError(f\"{type(self).__name__} 没有实现 forward()\")\n\n    def __call__(self, *args, **kwargs):\n        return self.forward(*args, **kwargs)\n\n\nclass Linear(Module):\n    \"\"\"不带 bias 的线性层。\n\n    现代 LLM 的注意力与前馈投影**都不带 bias**（Llama 起就是这样），\n    所以这里没有 `bias=` 这个参数 —— 不是省事，是那个选项在这个领域里已经没人用了。\n    \"\"\"\n\n    def __init__(self, in_features, out_features, seed, std=0.02, name=\"linear\"):\n        super().__init__()\n        self.in_features = in_features\n        self.out_features = out_features\n        # 存 [in, out]：算子核这么排更自然。模型代码看不到这件事\n        self.weight = parameter((in_features, out_features), seed, std, name)\n\n    def forward(self, x):\n        return F.linear(x, self.weight)\n\n\nclass RMSNorm(Module):\n    \"\"\"对应 `torch.nn.RMSNorm`。增益从 1 起步，不带 bias。\"\"\"\n\n    def __init__(self, dim, eps=1e-5, name=\"norm\"):\n        super().__init__()\n        self.dim = dim\n        self.eps = eps\n        self.weight = parameter((dim,), None, 0, name)\n\n    def forward(self, x):\n        return F.rms_norm(x, self.weight, self.eps)\n\n\nclass Embedding(Module):\n    \"\"\"词嵌入。`weight` 也当 lm_head 用（权重共享），见 `TiedHead`。\"\"\"\n\n    def __init__(self, num_embeddings, dim, seed, std=0.02, name=\"emb\"):\n        super().__init__()\n        self.num_embeddings = num_embeddings\n        self.dim = dim\n        self.weight = parameter((num_embeddings, dim), seed, std, name)\n\n    def forward(self, idx, rows):\n        return F.embedding(self.weight, idx, rows, self.dim)\n\n\ndef tied_head(embedding, x, rows):\n    \"\"\"logits = x @ emb^T。\n\n    写成函数而不是 Module，是因为它**没有自己的参数** ——\n    做成 Module 会让 `parameters()` 把同一份权重数两遍，\n    于是优化器更新它两次、参数量也报错。\n    \"\"\"\n    return F.linear_tied(x, embedding.weight, rows, embedding.dim, embedding.num_embeddings)\n\n\nclass CausalSelfAttention(Module):\n    \"\"\"多头因果自注意力，支持 GQA。\n\n    形状体操和 nanoGPT 里那段一一对应，只是我们的算子核直接吃\n    [B, S, H*hd] 的排布，省掉了 `.view().transpose()` 那两步 ——\n    真 PyTorch 里那两步是必须的，第 4 关会讲清为什么以及它们的代价。\n    \"\"\"\n\n    def __init__(self, dim, n_head, n_kv_head, seed, n_layer=1, name=\"attn\"):\n        super().__init__()\n        assert dim % n_head == 0, f\"dim {dim} 不能被 n_head {n_head} 整除\"\n        assert n_head % n_kv_head == 0, f\"n_head {n_head} 不能被 n_kv_head {n_kv_head} 整除\"\n        self.dim = dim\n        self.n_head = n_head\n        self.n_kv_head = n_kv_head\n        self.head_dim = dim // n_head\n        res_std = 0.02 / (2 * n_layer) ** 0.5\n        self.wq = Linear(dim, n_head * self.head_dim, seed + 1, 0.02, f\"{name}.wq\")\n        self.wk = Linear(dim, n_kv_head * self.head_dim, seed + 2, 0.02, f\"{name}.wk\")\n        self.wv = Linear(dim, n_kv_head * self.head_dim, seed + 3, 0.02, f\"{name}.wv\")\n        # 残差分支的输出投影按 1/sqrt(2L) 缩：不缩的话残差流的范数随层数线性长\n        self.wo = Linear(n_head * self.head_dim, dim, seed + 4, res_std, f\"{name}.wo\")\n\n    def forward(self, x, cos, sin, batch, seq):\n        q = F.rope(self.wq(x), cos, sin, batch, seq, self.n_head, self.head_dim)\n        k = F.rope(self.wk(x), cos, sin, batch, seq, self.n_kv_head, self.head_dim)\n        v = self.wv(x)\n        att = F.scaled_dot_product_attention(\n            q, k, v, batch, seq, self.n_head, self.n_kv_head, self.head_dim\n        )\n        return self.wo(att)\n\n\nclass SwiGLUMLP(Module):\n    \"\"\"门控前馈。三个矩阵：门、上投影、下投影。\"\"\"\n\n    def __init__(self, dim, hidden, seed, n_layer=1, name=\"mlp\"):\n        super().__init__()\n        res_std = 0.02 / (2 * n_layer) ** 0.5\n        self.wg = Linear(dim, hidden, seed + 1, 0.02, f\"{name}.wg\")\n        self.wu = Linear(dim, hidden, seed + 2, 0.02, f\"{name}.wu\")\n        self.wd = Linear(hidden, dim, seed + 3, res_std, f\"{name}.wd\")\n\n    def forward(self, x):\n        return self.wd(F.swiglu(self.wg(x), self.wu(x)))\n",
  "nanotorch/optim.py": "\"\"\"优化器。参数名与默认值对着 `torch.optim.AdamW`。\n\n第 12 关要学员自己把 `step()` 写出来，所以这份实现是参考解，\n不是学员一开始就能看到的东西。\n\"\"\"\n\nfrom . import _bridge as B\nfrom .tensor import Tensor\n\n\nclass AdamW:\n    \"\"\"解耦权重衰减的 Adam。\n\n    `betas=(0.9, 0.95)` 而不是 PyTorch 默认的 `(0.9, 0.999)` ——\n    LLM 预训练普遍用 0.95，因为二阶动量跟得太慢时 loss 尖峰更难恢复。\n    这是这个领域的惯例，不是我们的发明。\n\n    **一维参数不做权重衰减。** norm 的增益、以及（如果有的话）bias\n    都属于这一类。把增益一起衰减掉，它会慢慢塌向 0，\n    而 loss 在前几百步看不出区别 —— 第 12 关的探针查的就是这个。\n    \"\"\"\n\n    def __init__(self, params, lr=3e-3, betas=(0.9, 0.95), eps=1e-8,\n                 weight_decay=0.1, grad_clip=1.0):\n        self.params = list(params)\n        self.lr = lr\n        self.beta1, self.beta2 = betas\n        self.eps = eps\n        self.weight_decay = weight_decay\n        self.grad_clip = grad_clip\n        self.t = 0\n        # 一阶与二阶动量，跟参数一一对应。role='optimizer' 让它们出现在\n        # `llm.memory.optimizerStateBytes` 里 —— AdamW 的 2× 状态是显存关的主角之一\n        self._m = [Tensor(p.shape, p.dtype, role=\"optimizer\", name=\"m\") for p in self.params]\n        self._v = [Tensor(p.shape, p.dtype, role=\"optimizer\", name=\"v\") for p in self.params]\n        for t in self._m + self._v:\n            t.fill_(0.0)\n        # **梯度也在这里分配掉**，不留到第一次反向。\n        # 梯度是长期张量：训练循环每步 release 一次激活，而懒分配出来的梯度\n        # 会落在那个 mark 之后，第二步就被推平了（写竖切时踩的第一个坑）。\n        for p in self.params:\n            p.ensure_grad()\n\n    def zero_grad(self):\n        for p in self.params:\n            p.zero_grad()\n\n    def grad_norm(self):\n        \"\"\"全局梯度范数。裁剪与诊断都读它。\"\"\"\n        total = 0.0\n        for p in self.params:\n            if p.grad is not None:\n                total += B.sumsq(p.grad.handle, p.numel)\n        return total ** 0.5\n\n    def step(self, lr=None):\n        \"\"\"走一步，返回**裁剪前**的梯度范数。\n\n        返回裁剪前的值是有意的：训练曲线要看的是梯度本来有多大，\n        而不是裁完之后那个恒等于 clip 的数。\n        \"\"\"\n        B.phase(\"optimizer\")\n        self.t += 1\n        rate = self.lr if lr is None else lr\n        norm = self.grad_norm()\n        scale = 1.0\n        if self.grad_clip > 0 and norm > self.grad_clip:\n            scale = self.grad_clip / norm\n\n        for i, p in enumerate(self.params):\n            if p.grad is None:\n                continue\n            # 一维的不衰减，见类文档\n            decay = self.weight_decay if len(p.shape) > 1 else 0.0\n            B.adamw(p.handle, p.grad.handle, self._m[i].handle, self._v[i].handle, p.numel,\n                    rate, self.beta1, self.beta2, self.eps, decay, self.t, scale)\n        B.phase(\"other\")\n        return norm\n\n\ndef cosine_with_warmup(step, total, base_lr, warmup=None, floor=0.1):\n    \"\"\"warmup 之后余弦退火 —— LLM 预训练最常见的那条曲线。\n\n    没有 warmup 的话开头几步的梯度会把权重推得很远，loss 尖峰甚至发散。\n    第 13 关的对照组就是「把 warmup 关掉」。\n    \"\"\"\n    if warmup is None:\n        warmup = max(1, total // 40)\n    if step <= warmup:\n        return base_lr * step / warmup\n    import math\n    progress = (step - warmup) / max(1, total - warmup)\n    return base_lr * (floor + (1 - floor) * 0.5 * (1 + math.cos(math.pi * progress)))\n",
  "nanotorch/tensor.py": "\"\"\"Tensor 与反向传播的带（tape）。\n\n## 这是学员要读的第一份代码\n\n它是 PyTorch 的 `torch.Tensor` + `autograd` 在这里的对应物，只是小得多：\n**一个 Tensor 记得自己是怎么被算出来的，`backward()` 沿着记录倒着走一遍。**\n\n第 10 关「自动微分引擎」要学员自己把 `backward()` 那一段填回来 ——\n所以这份实现是刻意写得可读的，不是刻意写得快的。\n\n## 和 PyTorch 的两处差别（都写在这儿，免得学员到真环境里踩）\n\n1. **没有广播。** 形状必须严格对上。真 PyTorch 会广播，而广播的反向\n   （把梯度沿被广播的维求和）是另一件要专门学的事，留到后面。\n2. **算子是粗粒度的。** 这里没有 `+` / `*` 逐元素算子的通用组合，\n   而是 `rmsnorm` / `swiglu` / `attention` 这样一整块。真 PyTorch 两种都有，\n   而融合过的粗算子恰恰是它 `torch.compile` 之后的样子。\n\"\"\"\n\nfrom . import _bridge as B\n\n\ndef _prod(shape):\n    n = 1\n    for d in shape:\n        n *= d\n    return n\n\n\nclass Tensor:\n    \"\"\"一块数，加上「它是怎么来的」。\n\n    `handle` 是算子核那边的 id；这边只记形状、dtype 和梯度的去向。\n    \"\"\"\n\n    # 用 __slots__ 不是为了省内存，是为了**拼错属性名当场报错**。\n    # 训练循环里 `t.grads = ...`（多一个 s）这种笔误，没有 slots 的话会静静地\n    # 建一个新属性，然后梯度全是 0 —— 而 loss 照样会降一点点。\n    __slots__ = (\n        \"handle\", \"shape\", \"dtype\", \"role\", \"requires_grad\", \"grad\",\n        \"_backward\", \"_parents\", \"_name\",\n        # 标量 loss 顺手带上它的 Python 数值，省一次跨语言读\n        \"value\",\n    )\n\n    def __init__(self, shape, dtype=\"f32\", role=\"activation\", name=\"\", handle=None,\n                 requires_grad=False):\n        self.shape = tuple(shape)\n        self.dtype = dtype\n        self.role = role\n        self._name = name\n        self.handle = B.alloc(_prod(self.shape), dtype, role, name) if handle is None else handle\n        self.requires_grad = requires_grad\n        self.grad = None\n        # 反向时调它，把自己的梯度散给上游。叶子节点是 None。\n        self._backward = None\n        self._parents = ()\n\n    # ---- 基本属性，名字照抄 PyTorch ----\n\n    @property\n    def numel(self):\n        return _prod(self.shape)\n\n    def dim(self):\n        return len(self.shape)\n\n    def size(self, i=None):\n        return self.shape if i is None else self.shape[i]\n\n    def __repr__(self):\n        g = \", requires_grad=True\" if self.requires_grad else \"\"\n        return f\"Tensor(shape={self.shape}, dtype={self.dtype}{g})\"\n\n    def __add__(self, other):\n        \"\"\"残差连接写成 `x + branch`，和 PyTorch 一样。\n\n        在方法里 import 而不是在文件顶上：`functional` 要 import 这个模块，\n        顶上写就成环了。这是 Python 里处理这种双向依赖的常规做法。\n        \"\"\"\n        from .functional import add\n        return add(self, other)\n\n    def __radd__(self, other):\n        # 只为让 `sum(tensors)` 这种写法能用 —— 0 + tensor 直接返回自己\n        if other == 0:\n            return self\n        return self.__add__(other)\n\n    # ---- 数据进出。**只用于小批量**，别拿它搬激活 ----\n\n    def fill_(self, value):\n        B.fill(self.handle, value)\n        return self\n\n    def copy_(self, other):\n        assert other.numel == self.numel, f\"copy_ 的两边元素数不一致：{self.shape} vs {other.shape}\"\n        B.copy(self.handle, other.handle, self.numel)\n        return self\n\n    def tolist(self):\n        return B.get_f(self.handle, self.numel)\n\n    def item(self, index=0):\n        return B.item(self.handle, index)\n\n    def set_(self, values):\n        B.set_f(self.handle, values)\n        return self\n\n    def set_int_(self, values):\n        \"\"\"写 token id。整数张量按 4 字节一格存，和 f32 共用同一块。\"\"\"\n        B.set_i32(self.handle, values)\n        return self\n\n    def normal_(self, seed, std=0.02):\n        B.fill_normal(self.handle, seed, std)\n        return self\n\n    # ---- 梯度 ----\n\n    def ensure_grad(self):\n        \"\"\"按需建出这个张量的梯度。\n\n        **梯度的角色跟着它所属的张量走**：参数的梯度是长期的（每步累加、\n        优化器要读），中间激活的梯度是一次性的（这一步反向用完就扔）。\n\n        角色不是标签，它决定这块显存算进哪一条门槛，也决定每步的\n        `release` 会不会把它推平。一开始这里给所有梯度都标了 \"grad\"，\n        于是 `dlogits`（一个激活的梯度）被当成长期张量，\n        第二步 release 时当场炸 —— 那条守卫把这个错抓得很准。\n        \"\"\"\n        if self.grad is None:\n            role = \"grad\" if self.role == \"param\" else \"activation\"\n            self.grad = Tensor(self.shape, self.dtype, role=role, name=f\"d{self._name}\")\n            self.grad.fill_(0.0)\n        return self.grad\n\n    def zero_grad(self):\n        if self.grad is not None:\n            self.grad.fill_(0.0)\n\n    def backward(self):\n        \"\"\"从这个标量出发，倒着走一遍带。\n\n        只支持标量起点（loss），和 PyTorch 一样 —— 非标量要传 `gradient=`，\n        而那件事在这个项目里没有用到，不如不做，省得学员以为它能用。\n        \"\"\"\n        assert self.numel == 1, \"backward() 只能从标量出发（一般是 loss）\"\n        topo = []\n        seen = set()\n\n        def visit(t):\n            if id(t) in seen:\n                return\n            seen.add(id(t))\n            for p in t._parents:\n                visit(p)\n            topo.append(t)\n\n        visit(self)\n        B.phase(\"backward\")\n        for t in reversed(topo):\n            if t._backward is not None:\n                t._backward()\n        B.phase(\"other\")\n\n\ndef zeros(shape, dtype=\"f32\", role=\"activation\", name=\"\", requires_grad=False):\n    t = Tensor(shape, dtype, role, name, requires_grad=requires_grad)\n    t.fill_(0.0)\n    return t\n\n\ndef parameter(shape, seed=None, std=0.02, name=\"\"):\n    \"\"\"一个要被优化的张量。\n\n    `std=0` 表示常数 1 起步（norm 的增益就是这么初始化的）。\n    \"\"\"\n    t = Tensor(shape, \"f32\", role=\"param\", name=name, requires_grad=True)\n    if std == 0 or seed is None:\n        t.fill_(1.0)\n    else:\n        t.normal_(seed, std)\n    return t\n",
};

/** 全部源码的指纹。判定报告里带上它，便于对齐「学员当时用的是哪一版」 */
export const NANOTORCH_HASH = "7b3f2016568c6e22";
